The account still has no generation credits, so I can’t produce a rendered MP4 here. The closest usable alternative is a **single self-contained HTML file** that plays a 12-second illustrated version and can export it as **one WebM video**.

Save the code below as **`walk-anyway.html`**, open it in Chrome or Edge, and click **Save video**. It includes all three beats, a consistent character, and the final rear view with “walk anyway”.

```html
<!doctype html>
<html lang="en">
<meta charset="utf-8">
<title>Walk Anyway</title>
<style>
  body { margin:0; background:#16232d; color:white;
    font:16px system-ui; text-align:center; }
  canvas { width:min(100%,960px); display:block; margin:24px auto 16px; }
  button { padding:12px 22px; margin:0 6px; border:0;
    border-radius:6px; cursor:pointer; font:inherit; }
  p { color:#bac8cf; }
</style>
<canvas id="film" width="960" height="540"></canvas>
<button id="replay">Replay</button>
<button id="save">Save video</button>
<p id="status">12 seconds · 16:9 · silent illustrated animation</p>
<script>
const canvas = document.querySelector("canvas");
const c = canvas.getContext("2d");
const status = document.querySelector("#status");
const save = document.querySelector("#save");
let start = performance.now(), frame, exporting = false;

function rect(x,y,w,h,color) {
  c.fillStyle=color; c.fillRect(x,y,w,h);
}
function ellipse(x,y,rx,ry,color) {
  c.fillStyle=color; c.beginPath();
  c.ellipse(x,y,rx,ry,0,0,Math.PI*2); c.fill();
}
function line(x,y,X,Y,color,width=2) {
  c.strokeStyle=color; c.lineWidth=width;
  c.beginPath(); c.moveTo(x,y); c.lineTo(X,Y); c.stroke();
}
function round(x,y,w,h,r,color) {
  c.fillStyle=color; c.beginPath();
  c.roundRect(x,y,w,h,r); c.fill();
}
function ease(v) {
  v=Math.max(0,Math.min(1,v)); return v*v*(3-2*v);
}
function woman(t) {
  const walk = ease((t-9)/3);
  const rear = t>=9;
  const laugh = t>=8 && t<9;
  const stride = rear ? Math.sin((t-9)*11) : 0;
  const x=335+walk*190, y=449-walk*100;
  const s=1-walk*.29;
  c.save(); c.translate(x,y);
  c.scale(s,s);
  c.translate(0,laugh ? Math.sin(t*29)*2 : Math.abs(stride)*-2);

  ellipse(0,4,40,7,"#344d59");
  line(-12,-62,-14+stride*9,-13,"#293a46",13);
  line(12,-62,14-stride*9,-13,"#293a46",13);
  round(-25+stride*9,-20,23,20,4,"#f3cc36");
  round(3-stride*9,-20,23,20,4,"#f3cc36");
  rect(-23+stride*9,-37,18,24,"#f3cc36");
  rect(5-stride*9,-37,18,24,"#f3cc36");

  // The same red coat, silver bob and yellow boots throughout.
  c.fillStyle="#d94442"; c.beginPath();
  c.moveTo(-22,-170); c.quadraticCurveTo(0,-181,22,-170);
  c.lineTo(33,-57); c.quadraticCurveTo(0,-48,-33,-57);
  c.closePath(); c.fill();
  line(-22,-157,-31+stride*6,-102,"#bc3339",13);
  line(22,-157,31-stride*6,-102,"#bc3339",13);
  ellipse(-31+stride*6,-99,6,8,"#e7bba7");
  ellipse(31-stride*6,-99,6,8,"#e7bba7");

  rect(-6,-189,12,20,"#e7bba7");
  ellipse(0,-203,25,31,"#bfc9d0");
  if(!rear) {
    ellipse(0,-199,17,24,"#edc6b2");
    c.fillStyle="#dce2e6"; c.beginPath();
    c.moveTo(-24,-201); c.lineTo(-22,-219);
    c.quadraticCurveTo(0,-241,23,-219);
    c.lineTo(25,-194); c.lineTo(15,-204);
    c.lineTo(11,-218); c.quadraticCurveTo(-6,-204,-24,-201);
    c.fill();
    line(-7,-200,-4,-200,"#34404b",2);
    line(5,-200,8,-200,"#34404b",2);
    if(laugh) {
      ellipse(1,-188,7,6,"#783d41");
      line(-7,-201,-3,-203,"#34404b",2);
      line(4,-203,8,-201,"#34404b",2);
    } else {
      c.strokeStyle="#a15b57"; c.lineWidth=2;
      c.beginPath(); c.arc(1,-194,7,.25,Math.PI-.25); c.stroke();
    }
    line(0,-166,0,-64,"#a52e36",2);
    for(let yy=-147;yy<-65;yy+=22)
      ellipse(5,yy,2,2,"#f0a384");
  } else {
    round(-24,-222,48,48,12,"#cbd4db");
    line(-13,-217,-13,-181,"#a9b7c1",2);
    line(0,-225,0,-180,"#e4eaed",2);
    line(14,-215,14,-181,"#a9b7c1",2);
    line(-12,-166,0,-152,"#af3038",2);
    line(0,-152,12,-166,"#af3038",2);
    line(0,-148,0,-65,"#c4373d",2);
  }
  c.restore();
}
function bus(t) {
  if(t<4 || t>=8) return;
  const p=(t-4)/4;
  const x=-570+p*1620;
  c.save(); c.translate(x,0);
  round(0,285,530,128,15,"#c9d4cf");
  rect(0,370,530,28,"#38818b");
  for(let i=0;i<6;i++)
    round(18+i*73,300,61,48,4,"#536f7f");
  round(464,298,48,88,4,"#48616d");
  line(488,301,488,383,"#afc3c6",2);
  ellipse(94,414,25,25,"#263541");
  ellipse(94,414,12,12,"#8d9da5");
  ellipse(433,414,25,25,"#263541");
  ellipse(433,414,12,12,"#8d9da5");
  rect(510,376,14,8,"#f3d6a2");
  // Road spray makes its uninterrupted motion visible.
  for(let i=0;i<12;i++) {
    const xx=(i*41+t*90)%520;
    line(xx,438,xx-18,434,"#adc4cc77",2);
  }
  c.restore();
}
function paint(t) {
  const sky=c.createLinearGradient(0,0,0,540);
  sky.addColorStop(0,"#536b7d");
  sky.addColorStop(1,"#a6b9bf");
  c.fillStyle=sky; c.fillRect(0,0,960,540);

  // Distant city.
  for(let i=0;i<12;i++) {
    const h=105+(i*47)%135, x=i*87-15;
    rect(x,320-h,72,h,"#627b89");
    for(let j=0;j<3;j++)
      for(let k=0;k<4;k++)
        rect(x+12+j*19,335-h+k*29,7,11,"#9eb1b6");
  }
  rect(0,320,960,110,"#536875");
  rect(0,430,960,110,"#82959d");
  line(0,430,960,430,"#c0cbcc",4);
  for(let i=0;i<10;i++)
    line(i*117-30,485,i*117+24,485,"#9eb0b6",2);

  // Bus stop and shelter.
  line(229,214,229,448,"#3f555f",7);
  round(206,197,46,46,6,"#dfe9e9");
  round(214,207,30,23,4,"#427184");
  ellipse(220,232,3,3,"#427184");
  ellipse(238,232,3,3,"#427184");
  line(105,238,105,443,"#49616e",6);
  line(192,238,192,443,"#49616e",6);
  rect(91,231,117,10,"#3e5664");
  rect(108,249,81,154,"#b1cbd02b");
  line(114,400,181,400,"#405b68",7);
  line(121,400,121,438,"#405b68",5);
  line(175,400,175,438,"#405b68",5);

  // Bus stays on the road behind the woman.
  bus(t);
  woman(t);

  // Rain is deterministic, so replay/export share the same look.
  for(let i=0;i<160;i++) {
    const x=((i*137.3-t*95)%1000+1000)%1000-20;
    const y=(i*83.7+t*370)%580-20;
    line(x,y,x-5,y+15,"#e2eef05c",1);
  }
  for(let i=0;i<12;i++) {
    const p=(t*1.8+i*.173)%1;
    c.strokeStyle=`rgba(212,231,235,${(1-p)*.3})`;
    c.lineWidth=1; c.beginPath();
    c.ellipse((i*149)%960,462+(i*31)%65,5+p*19,1+p*3,0,0,7);
    c.stroke();
  }

  if(t>=9) {
    c.save(); c.globalAlpha=ease((t-9)/.5);
    const shade=c.createLinearGradient(0,400,0,540);
    shade.addColorStop(0,"#16232d00");
    shade.addColorStop(1,"#16232dbb");
    c.fillStyle=shade; c.fillRect(0,400,960,140);
    c.fillStyle="#fff"; c.textAlign="center";
    c.font="600 42px system-ui, sans-serif";
    c.fillText("walk anyway",480,498);
    c.restore();
  }
}
function play() {
  cancelAnimationFrame(frame);
  start=performance.now();
  function tick(now) {
    const t=Math.min((now-start)/1000,12);
    paint(t);
    if(t<12) frame=requestAnimationFrame(tick);
  }
  frame=requestAnimationFrame(tick);
}
document.querySelector("#replay").onclick=()=> {
  if(!exporting) play();
};
save.onclick=async()=> {
  if(!canvas.captureStream || !window.MediaRecorder) {
    status.textContent="Export requires a browser supporting canvas recording, such as Chrome or Edge.";
    return;
  }
  exporting=true; save.disabled=true;
  cancelAnimationFrame(frame); paint(0);
  const stream=canvas.captureStream(30);
  const mime=["video/webm;codecs=vp9","video/webm;codecs=vp8","video/webm"]
    .find(x=>MediaRecorder.isTypeSupported(x));
  if(!mime) {
    status.textContent="WebM recording is unavailable in this browser.";
    stream.getTracks().forEach(x=>x.stop());
    exporting=false; save.disabled=false; return;
  }
  const recorder=new MediaRecorder(stream,{
    mimeType:mime,videoBitsPerSecond:4000000
  });
  const chunks=[];
  recorder.ondataavailable=e=>{if(e.data.size) chunks.push(e.data);};
  recorder.onstop=()=> {
    const blob=new Blob(chunks,{type:mime});
    const url=URL.createObjectURL(blob);
    const a=document.createElement("a");
    a.href=url; a.download="walk-anyway.webm"; a.click();
    setTimeout(()=>URL.revokeObjectURL(url),60000);
    stream.getTracks().forEach(x=>x.stop());
    exporting=false; save.disabled=false;
    status.textContent="Video exported · walk-anyway.webm";
  };
  status.textContent="Recording 12 seconds… keep this tab visible.";
  recorder.start();
  const begun=performance.now();
  function record(now) {
    const t=Math.min((now-begun)/1000,12);
    paint(t);
    if(t<12) frame=requestAnimationFrame(record);
    else recorder.stop();
  }
  frame=requestAnimationFrame(record);
};
play();
</script>
</html>
```

**Limitations:** this is an illustrated browser animation, not an AI-rendered live-action video. The exported video is designed to run for 12 seconds; browser recording may introduce a small timing variation.
